# calculator.py\n\n"""\nSimple calculator module providing basic arithmetic operations.\n\nFunctions:\n- add(a, b)\n- subtract(a, b)\n- multiply(a, b)\n- divide(a, b)\n\nAll functions accept numbers (int or float) and return a float result.\n"""\n\ndef add(a, b):\n    """Return the sum of a and b."""\n    return a + b\n\n\ndef subtract(a, b):\n    """Return the difference of a and b (a - b)."""\n    return a - b\n\n\ndef multiply(a, b):\n    """Return the product of a and b."""\n    return a * b\n\n\ndef divide(a, b):\n    """Return the division of a by b.\n    Raises:\n        ZeroDivisionError: If b is zero.\n    """\n    if b == 0:\n        raise ZeroDivisionError("Division by zero is undefined.")\n    return a / b\n\n# Mapping of operator symbols to functions for easy lookup\nOPERATIONS = {\n    '+': add